"use strict";exports.id=3713,exports.ids=[3713],exports.modules={43713:(a,b,c)=>{c.d(b,{Ob:()=>d,WS:()=>f,bO:()=>e,yV:()=>g,z0:()=>h});let d=(a=["draft"])=>({from:a,to:"approved",past:"approved",label:"Approve",icon:"bi-check2-circle"}),e=a=>({from:a,to:"cancelled",past:"cancelled",label:"Cancel",icon:"bi-slash-circle"}),f=a=>({from:a,to:"draft",past:"reopened",label:"Reopen",icon:"bi-arrow-counterclockwise"}),g=a=>({from:a,to:"rejected",past:"rejected",label:"Reject",icon:"bi-x-circle"}),h={"sales-quotation":{key:"sales-quotation",endpoint:"quotations",table:"sales_quotations",items:"sales_quotation_items",parentKey:"quotation_id",noColumn:"quotation_no",dateColumn:"quotation_date",party:"customer",hasSalesperson:!0,inTransferChain:!0,module:"sales_quotations",numbering:{module:"SALES",type:"Sales Quotation"},noun:"quotation",label:"Quotation",plural:"Quotations",view:"sales-quotations",printTitle:"Sales Quotation",subtitle:"What was quoted, to whom, and what it became. A quotation has no accounting effect until it becomes an order or an invoice.",statuses:["draft","approved","rejected","cancelled"],editable:["draft"],transitions:{approve:d(),reject:{from:["draft","approved"],to:"rejected",past:"rejected",label:"Reject",icon:"bi-x-circle"},cancel:e(["draft","approved"]),reopen:f(["rejected","cancelled"])},extras:[{column:"valid_until",label:"Valid Until",kind:"date",hint:"Leave blank if the quotation does not expire.",print:"Valid Until",list:"Valid Until",notBefore:"quotation_date",notBeforeReason:"A quotation cannot expire before the day it was raised."}],hasPaymentTerms:!0,posts:!1,registerNote:"A quotation posts nothing to the ledger. It becomes an accounting document when it is converted to a sales order or an invoice, and what it became is read from `document_transfers` rather than from the single `conversion_status` column, which has room for one target where a quotation can produce several."},"sales-order":{key:"sales-order",endpoint:"sales-orders",table:"sales_orders",items:"sales_order_items",parentKey:"order_id",noColumn:"order_no",dateColumn:"order_date",party:"customer",hasSalesperson:!0,inTransferChain:!0,module:"sales_orders",numbering:{module:"SALES",type:"Sales Order"},noun:"sales order",label:"Sales Order",plural:"Sales Orders",view:"sales-orders",printTitle:"Sales Order",subtitle:"What a customer has confirmed, and what it became. A sales order posts nothing to the ledger — the invoice raised from it does.",statuses:["draft","approved","processing","completed","cancelled"],editable:["draft"],transitions:{approve:d(),cancel:e(["draft","approved"]),reopen:f(["cancelled"])},derivedStatuses:["processing","completed"],extras:[{column:"po_no",label:"Customer PO No.",kind:"text",maxLength:100,hint:"The number the CUSTOMER will quote when they pay. Printed on the order.",print:"P.O. No.",list:"Their PO",printAlways:!0}],hasPaymentTerms:!0,posts:!1,registerNote:"Processing and completed are NOT offered as buttons. They describe how much of the order has been delivered, and that is already derived from the transferred quantities in the Transferred column — a second copy set by hand would disagree with it the first time a delivery order was deleted."},"delivery-order":{key:"delivery-order",endpoint:"delivery-orders",table:"delivery_orders",items:"delivery_order_items",parentKey:"delivery_order_id",noColumn:"do_no",dateColumn:"do_date",party:"customer",hasSalesperson:!0,inTransferChain:!0,module:"sales_delivery",numbering:{module:"SALES",type:"Delivery Order"},noun:"delivery order",label:"Delivery Order",plural:"Delivery Orders",view:"sales-delivery-orders",printTitle:"Delivery Order",subtitle:"What was sent, to where, and against which order. A delivery moves goods, not money — under this chart it posts nothing.",statuses:["draft","approved","delivered","cancelled"],editable:["draft"],transitions:{approve:d(),deliver:{from:["approved"],to:"delivered",past:"marked delivered",label:"Mark Delivered",icon:"bi-truck"},cancel:e(["draft","approved"]),reopen:f(["cancelled"])},extras:[],hasPaymentTerms:!0,posts:!1,registerNote:"A delivery order posts nothing to the ledger. There is no perpetual stock ledger in this chart, so moving goods has no journal — the invoice raised against the delivery is what reaches the accounts."},"proforma-invoice":{key:"proforma-invoice",endpoint:"proforma-invoices",table:"proforma_invoices",items:"proforma_invoice_items",parentKey:"proforma_id",noColumn:"proforma_no",dateColumn:"proforma_date",party:"customer",hasSalesperson:!0,inTransferChain:!0,module:"sales_proforma",numbering:{module:"SALES",type:"Proforma Invoice"},noun:"proforma invoice",label:"Proforma Invoice",plural:"Pro-forma Invoices",view:"sales-proforma-invoices",printTitle:"Proforma Invoice",subtitle:"A request for payment before the sale is recognised. A proforma raises no journal and is not an e-Invoice — it asks for money, it does not report a sale.",statuses:["draft","approved","paid","cancelled"],editable:["draft"],transitions:{approve:d(),cancel:e(["draft","approved"]),reopen:f(["cancelled"])},derivedStatuses:["paid"],extras:[{column:"bank_name",label:"Bank",kind:"text",maxLength:255,hint:"Printed under Note, so the customer knows where to pay."},{column:"bank_account_name",label:"Account Name",kind:"text",maxLength:255},{column:"bank_account_number",label:"Account No.",kind:"text",maxLength:100}],hasPaymentTerms:!0,posts:!1,registerNote:"There is no Mark Paid button, and that is deliberate. A proforma asks for a deposit, and what was actually received is recorded in Money > Receivables > Receive Payments — the status follows the receipt. A button here could mark a proforma paid with no money behind it, and nothing in the accounts could contradict it.",noNewDocuments:"A sales order already prints as a proforma invoice, and that sheet carries the order number. Raising a separate proforma document would give one sale two references, so new ones are closed. Print the proforma from the sales order instead. The proforma invoices already here stay fully editable."},"sales-invoice":{key:"sales-invoice",endpoint:"sales-invoices",table:"sales_invoices",items:"sales_invoice_items",parentKey:"invoice_id",noColumn:"invoice_no",dateColumn:"invoice_date",party:"customer",hasSalesperson:!0,inTransferChain:!0,module:"sales_invoices",numbering:{module:"SALES",type:"Sales Invoice"},noun:"invoice",label:"Sales Invoice",plural:"Sales Invoices",view:"sales-invoices",printTitle:"Tax Invoice",subtitle:"The issued sale that creates a customer balance and can be submitted to LHDN. An approved invoice is not edited — it is credited and reissued.",statuses:["draft","approved","paid","cancelled"],editable:["draft"],transitions:{approve:d(),cancel:e(["draft"]),reopen:f(["cancelled"])},derivedStatuses:["paid"],extras:[{column:"due_date",label:"Due Date",kind:"date",print:"Due Date",list:"Due",hint:"When payment is expected. Leave blank to use the payment terms.",notBefore:"invoice_date",notBeforeReason:"An invoice cannot fall due before the day it was issued."},{column:"einvoice_status",label:"e-Invoice",kind:"readonly"},{column:"einvoice_uuid",label:"e-Invoice UUID",kind:"readonly"}],hasPaymentTerms:!0,posts:!0,receivable:{direction:"increase"},registerNote:"An invoice does NOT post itself. It is posted from General Ledger > Document Posting, which is where the double entry is made and where a failed posting can be seen. There is no Mark Paid button either: what has been received is recorded in Money > Receivables > Receive Payments, and the Balance column here is derived from the receipts and credit notes allocated against the invoice. The e-Invoice fields are written by the MyInvois submission and cannot be typed here — a screen that could type a UUID is a screen that can claim a document was filed when it was not.",reversedBy:[{table:"sales_credit_notes",column:"original_invoice_id",noun:"credit note",noColumn:"credit_note_no"},{table:"sales_debit_notes",column:"original_invoice_id",noun:"debit note",noColumn:"debit_note_no"}]},"sales-credit-note":{key:"sales-credit-note",endpoint:"sales-credit-notes",table:"sales_credit_notes",items:"sales_credit_note_items",parentKey:"credit_note_id",noColumn:"credit_note_no",dateColumn:"credit_note_date",party:"customer",hasSalesperson:!0,inTransferChain:!1,module:"sales_credit_notes",numbering:{module:"SALES",type:"Sales Credit Note"},noun:"credit note",label:"Credit Note",plural:"Credit Notes",view:"sales-credit-notes",printTitle:"Credit Note",subtitle:"Reduces what a customer owes. A credit note REVERSES a sale rather than continuing one, so it is not part of the transfer chain and it carries its own reason.",statuses:["draft","approved","cancelled"],editable:["draft"],transitions:{approve:d(),cancel:e(["draft"]),reopen:f(["cancelled"])},extras:[{column:"reason",label:"Reason",kind:"text",maxLength:500,hint:"Why the customer is being credited. Printed on the note — a credit with no reason is a credit somebody has to ask about.",print:"Reason"},{column:"original_invoice_no",label:"Against Invoice",kind:"text",maxLength:50,hint:"The invoice number this credits.",print:"Against Invoice",list:"Invoice"}],hasPaymentTerms:!0,posts:!0,receivable:{direction:"decrease",appliedTo:"original_invoice_id"},adjusts:{table:"sales_invoices",lookupColumn:"invoice_no",numberColumn:"original_invoice_no",idColumn:"original_invoice_id",noun:"invoice"},registerNote:"A credit note is NOT a transfer. It reverses a sale rather than continuing one, which is why it has its own tables and its own reason field and why nothing transfers out of it. Like an invoice, it is posted from General Ledger > Document Posting."},"sales-debit-note":{key:"sales-debit-note",endpoint:"sales-debit-notes",table:"sales_debit_notes",items:"sales_debit_note_items",parentKey:"debit_note_id",noColumn:"debit_note_no",dateColumn:"debit_note_date",party:"customer",hasSalesperson:!0,inTransferChain:!1,module:"sales_debit_notes",numbering:{module:"SALES",type:"Sales Debit Note"},noun:"debit note",label:"Debit Note",plural:"Debit Notes",view:"sales-debit-notes",printTitle:"Debit Note",subtitle:"Charges a customer MORE against an invoice already issued. Separate from a credit note because charging more is a different authority from crediting.",statuses:["draft","approved","cancelled"],editable:["draft"],transitions:{approve:d(),cancel:e(["draft"]),reopen:f(["cancelled"])},extras:[{column:"reason",label:"Reason",kind:"text",maxLength:500,hint:"Why the customer is being charged more. Printed on the note.",print:"Reason"},{column:"original_invoice_no",label:"Against Invoice",kind:"text",maxLength:50,hint:"The invoice number this adds to.",print:"Against Invoice",list:"Invoice"}],hasPaymentTerms:!0,posts:!0,receivable:{direction:"increase"},adjusts:{table:"sales_invoices",lookupColumn:"invoice_no",numberColumn:"original_invoice_no",idColumn:"original_invoice_id",noun:"invoice"},registerNote:"A debit note is kept separate from a credit note on purpose: reducing what a customer owes and charging them more are different authorities, and one screen for both makes the wrong one one click away. The invoice named in Against Invoice is matched when the note is saved: a number that names no invoice of this customer is refused, because a note against nothing is a figure no report can place."},"cash-sale":{key:"cash-sale",endpoint:"cash-sales",table:"cash_sales",items:"cash_sales_items",parentKey:"cash_sale_id",noColumn:"receipt_no",dateColumn:"receipt_date",party:"customer",hasSalesperson:!0,inTransferChain:!0,module:"sales_cash",numbering:{module:"SALES",type:"Cash Sales"},noun:"cash sale",label:"Cash Sale",plural:"Cash Sales",view:"sales-cash-sales",printTitle:"Cash Sale Receipt",subtitle:"Sold and paid at the same moment. A cash sale has no payment terms and nothing to chase — the money is recorded against the account it was banked into.",statuses:["draft","approved","cancelled"],editable:["draft"],transitions:{approve:d(),cancel:e(["draft"]),reopen:f(["cancelled"])},extras:[{column:"payment_method",label:"Paid By",kind:"select",options:"payment_methods",required:!0,maxLength:50,hint:"A closed list, because the column is an enum. A bank transfer is EFT.",print:"Paid By",list:"Paid By"},{column:"reference_no",label:"Payment Ref.",kind:"text",maxLength:100,hint:"Cheque number, transfer reference, terminal slip.",print:"Payment Ref."},{column:"deposit_to_account_id",label:"Deposited To",kind:"select",options:"bank_accounts",required:!0,snapshot:{codeColumn:"deposit_to_account_code",nameColumn:"deposit_to_account_name"},hint:"Cash and bank accounts only. This is the account the money landed in.",print:"Deposited To",list:"Banked Into"}],hasPaymentTerms:!1,posts:!0,registerNote:"A cash sale is paid when it is made, so it has no payment terms and never appears on an ageing report. Post it from General Ledger > Document Posting: the selected bank or cash account is debited, and the revenue and output tax accounts are credited."}}}};